1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列。
14	
15	import http from 'node:http';
16	import { readFile } from 'node:fs/promises';
17	import path from 'node:path';
18	
19	const APP_NAME = 'contractlab';
20	
21	// 管理入口（保留前缀，业务接口不得使用）
22	const ADMIN_PREFIX = '/__contractlab/';
23	const HEALTH_PATH = '/__contractlab/health';
24	const RELOAD_PATH = '/__contractlab/reload';
25	
26	// 每个业务响应都携带当前配置版本
27	const VERSION_HEADER = 'X-Contractlab-Version';
28	
29	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
30	const MAX_BODY_BYTES = 100 * 1024 * 1024;
31	
32	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
33	const BLOCKED_HEADERS = new Set([
34	  'connection',
35	  'keep-alive',
36	  'content-length',
37	  'transfer-encoding',
38	]);
39	
40	// RFC 7230 token：合法的 HTTP 头名称字符
41	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
42	
43	type HttpMethod = 'GET' | 'POST';
44	
45	interface ResponseSpec {
46	  readonly status: number;
47	  readonly headers: { readonly [name: string]: string };
48	  readonly body: string;
49	  readonly delay: number;
50	}
51	
52	interface EndpointSpec {
53	  readonly method: HttpMethod;
54	  readonly path: string;
55	  readonly responses: readonly ResponseSpec[];
56	}
57	
58	interface LiveEndpoint {
59	  readonly key: string;
60	  readonly responses: readonly ResponseSpec[];
61	  // 下一个待预留位置；到达末项后停在末项（持续复用）
62	  cursor: number;
63	}
64	
65	interface LiveState {
66	  readonly version: number;
67	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
68	}
69	
70	interface ReloadResult {
71	  ok: boolean;
72	  version: number;
73	  error?: string;
74	}
75	
76	class ConfigError extends Error {
77	  constructor(message: string) {
78	    super(message);
79	    this.name = 'ConfigError';
80	  }
81	}
82	
83	// ---------------------------------------------------------------------------
84	// 配置校验
85	// ---------------------------------------------------------------------------
86	
87	function isPlainObject(value: unknown): value is Record<string, unknown> {
88	  return typeof value === 'object' && value !== null && !Array.isArray(value);
89	}
90	
91	function validatePath(p: string, where: string): void {
92	  if (p.length === 0 || p[0] !== '/') {
93	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
94	  }
95	  if (p.length > 4096) {
96	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
97	  }
98	  for (const ch of p) {
99	    const code = ch.charCodeAt(0);
100	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
101	      throw new ConfigError(
102	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
103	      );
104	    }
105	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
106	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
107	    }
108	  }
109	}
110	
111	function validateResponse(raw: unknown, where: string): ResponseSpec {
112	  if (!isPlainObject(raw)) {
113	    throw new ConfigError(`${where} 必须是对象`);
114	  }
115	  for (const key of Object.keys(raw)) {
116	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
117	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
118	    }
119	  }
120	
121	  const { status, headers, body, delay } = raw;
122	
123	  if (!Number.isInteger(status) || status < 200 || status > 599) {
124	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
125	  }
126	
127	  if (!isPlainObject(headers)) {
128	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
129	  }
130	  const cleanHeaders: { [name: string]: string } = {};
131	  const seenNames = new Set<string>();
132	  for (const [name, value] of Object.entries(headers)) {
133	    const whereHeader = `${where}.headers["${name}"]`;
134	    if (!HEADER_NAME_RE.test(name)) {
135	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
136	    }
137	    const lower = name.toLowerCase();
138	    if (BLOCKED_HEADERS.has(lower)) {
139	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
140	    }
141	    if (seenNames.has(lower)) {
142	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
143	    }
144	    if (typeof value !== 'string') {
145	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
146	    }
147	    for (let i = 0; i < value.length; i += 1) {
148	      const code = value.charCodeAt(i);
149	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
150	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
151	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
152	        throw new ConfigError(
153	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
154	        );
155	      }
156	    }
157	    seenNames.add(lower);
158	    cleanHeaders[name] = value;
159	  }
160	
161	  if (typeof body !== 'string') {
162	    throw new ConfigError(`${where}.body 必须是文本字符串`);
163	  }
164	  if ((status === 204 || status === 304) && body !== '') {
165	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
166	  }
167	
168	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
169	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
170	  }
171	
172	  return { status, headers: cleanHeaders, body, delay };
173	}
174	
175	function validateEndpoint(
176	  raw: unknown,
177	  index: number,
178	  seen: Set<string>,
179	): EndpointSpec {
180	  const where = `endpoints[${index}]`;
181	  if (!isPlainObject(raw)) {
182	    throw new ConfigError(`${where} 必须是对象`);
183	  }
184	  for (const key of Object.keys(raw)) {
185	    if (key !== 'method' && key !== 'path' && key !== 'responses') {
186	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
187	    }
188	  }
189	
190	  const { method, path: routePath, responses } = raw;
191	
192	  if (method !== 'GET' && method !== 'POST') {
193	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
194	  }
195	
196	  if (typeof routePath !== 'string') {
197	    throw new ConfigError(`${where}.path 必须是字符串`);
198	  }
199	  validatePath(routePath, where);
200	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
201	    throw new ConfigError(
202	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
203	    );
204	  }
205	
206	  const key = `${method} ${routePath}`;
207	  if (seen.has(key)) {
208	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
209	  }
210	  seen.add(key);
211	
212	  if (!Array.isArray(responses) || responses.length === 0) {
213	    throw new ConfigError(`${where}.responses 必须是非空数组`);
214	  }
215	  const cleanResponses = responses.map((item, j) =>
216	    validateResponse(item, `${where}.responses[${j}]`),
217	  );
218	
219	  return { method, path: routePath, responses: cleanResponses };
220	}
221	
222	function validateConfig(raw: unknown): EndpointSpec[] {
223	  if (!isPlainObject(raw)) {
224	    throw new ConfigError('配置顶层必须是 JSON 对象');
225	  }
226	  for (const key of Object.keys(raw)) {
227	    if (key !== 'endpoints') {
228	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
229	    }
230	  }
231	  const list = raw.endpoints;
232	  if (!Array.isArray(list) || list.length === 0) {
233	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
234	  }
235	  const seen = new Set<string>();
236	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
237	}
238	
239	// ---------------------------------------------------------------------------
240	// 运行时状态：配置快照 + 每接口独立序列
241	// ---------------------------------------------------------------------------
242	
243	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
244	  const endpoints = new Map<string, LiveEndpoint>();
245	  for (const spec of specs) {
246	    endpoints.set(`${spec.method} ${spec.path}`, {
247	      key: `${spec.method} ${spec.path}`,
248	      responses: spec.responses,
249	      cursor: 0,
250	    });
251	  }
252	  return { version, endpoints };
253	}
254	
255	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
256	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
257	function reserveNext(endpoint: LiveEndpoint): ResponseSpec {
258	  const last = endpoint.responses.length - 1;
259	  const position = endpoint.cursor < last ? endpoint.cursor : last;
260	  if (endpoint.cursor < last) {
261	    endpoint.cursor += 1;
262	  }
263	  return endpoint.responses[position];
264	}
265	
266	// ---------------------------------------------------------------------------
267	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
268	// ---------------------------------------------------------------------------
269	
270	function describeError(e: unknown): string {
271	  return e instanceof Error ? e.message : String(e);
272	}
273	
274	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
275	  let text: string;
276	  try {
277	    text = await readFile(configPath, 'utf8');
278	  } catch (e) {
279	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
280	  }
281	
282	  let raw: unknown;
283	  try {
284	    raw = JSON.parse(text);
285	  } catch (e) {
286	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
287	  }
288	
289	  try {
290	    const specs = validateConfig(raw);
291	    return buildState(version, specs);
292	  } catch (e) {
293	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
294	  }
295	}
296	
297	// ---------------------------------------------------------------------------
298	// HTTP 服务
299	// ---------------------------------------------------------------------------
300	
301	// 模块级运行时句柄（启动后赋值）
302	let activeState: LiveState;
303	let server: http.Server;
304	let configFile = '';
305	let shuttingDown = false;
306	
307	// 尚未发出的延迟响应定时器，关闭时统一取消
308	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
309	
310	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
311	let reloadChain: Promise<unknown> = Promise.resolve();
312	
313	function triggerReload(): Promise<ReloadResult> {
314	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
315	    try {
316	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
317	      const next = await loadStateFromFile(configFile, activeState.version + 1);
318	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
319	      return { ok: true, version: activeState.version };
320	    } catch (e) {
321	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
322	      return { ok: false, version: activeState.version, error: describeError(e) };
323	    }
324	  });
325	  // 失败也不能打断后续 reload 的排队
326	  reloadChain = job.then(
327	    () => undefined,
328	    () => undefined,
329	  );
330	  return job;
331	}
332	
333	function writeResponse(
334	  res: http.ServerResponse,
335	  status: number,
336	  headers: { readonly [name: string]: string },
337	  body: string,
338	): void {
339	  try {
340	    res.writeHead(status, headers);
341	    res.end(body === '' ? undefined : body);
342	  } catch {
343	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
344	  }
345	}
346	
347	function versionHeaders(
348	  version: number,
349	  extra?: { readonly [name: string]: string },
350	): { [name: string]: string } {
351	  const headers: { [name: string]: string } = {
352	    [VERSION_HEADER]: String(version),
353	  };
354	  if (extra) {
355	    for (const [name, value] of Object.entries(extra)) {
356	      headers[name] = value;
357	    }
358	  }
359	  return headers;
360	}
361	
362	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
363	  writeResponse(
364	    res,
365	    status,
366	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
367	    `${JSON.stringify(value)}\n`,
368	  );
369	}
370	
371	function sendNotFound(res: http.ServerResponse): void {
372	  writeResponse(
373	    res,
374	    404,
375	    versionHeaders(activeState.version, {
376	      'Content-Type': 'text/plain; charset=utf-8',
377	    }),
378	    'not found\n',
379	  );
380	}
381	
382	function sendBusinessResponse(
383	  res: http.ServerResponse,
384	  item: ResponseSpec,
385	  version: number,
386	): void {
387	  const headers = versionHeaders(version);
388	  let contentTypeSet = false;
389	  for (const [name, value] of Object.entries(item.headers)) {
390	    if (name.toLowerCase() === 'content-type') {
391	      contentTypeSet = true;
392	    }
393	    headers[name] = value;
394	  }
395	  // 文本正文的默认内容类型；配置显式给出时不覆盖
396	  if (!contentTypeSet && item.body !== '') {
397	    headers['Content-Type'] = 'text/plain; charset=utf-8';
398	  }
399	  writeResponse(res, item.status, headers, item.body);
400	}
401	
402	// 延迟结束才发送；即便客户端提前断开也继续计时（消费在预留时已经成立）
403	function scheduleBusinessResponse(
404	  res: http.ServerResponse,
405	  item: ResponseSpec,
406	  version: number,
407	): void {
408	  const timer = setTimeout(() => {
409	    pendingTimers.delete(timer);
410	    sendBusinessResponse(res, item, version);
411	  }, item.delay);
412	  pendingTimers.add(timer);
413	}
414	
415	type BodyOutcome = 'received' | 'aborted' | 'too-large';
416	
417	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
418	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<BodyOutcome> {
419	  return new Promise((resolve) => {
420	    let settled = false;
421	    let size = 0;
422	    const finish = (outcome: BodyOutcome): void => {
423	      if (!settled) {
424	        settled = true;
425	        resolve(outcome);
426	      }
427	    };
428	    req.on('data', (chunk: Buffer) => {
429	      size += chunk.byteLength;
430	      if (size > MAX_BODY_BYTES) {
431	        finish('too-large');
432	        writeResponse(
433	          res,
434	          413,
435	          versionHeaders(activeState.version, {
436	            'Content-Type': 'text/plain; charset=utf-8',
437	          }),
438	          'payload too large\n',
439	        );
440	        // 等 413 刷出后再断开，避免客户端收不到响应
441	        res.once('finish', () => req.socket.destroy());
442	      }
443	    });
444	    req.on('end', () => finish('received'));
445	    req.on('error', () => finish('aborted'));
446	    req.on('aborted', () => finish('aborted'));
447	    res.on('close', () => finish('aborted'));
448	  });
449	}
450	
451	async function dispatch(
452	  req: http.IncomingMessage,
453	  res: http.ServerResponse,
454	): Promise<void> {
455	  res.on('error', () => {
456	    // 写已销毁套接字等错误无需让进程崩溃
457	  });
458	
459	  const outcome = await receiveBody(req, res);
460	  if (outcome !== 'received') {
461	    // aborted：未完整接收，不匹配、不预留、不推进任何序列
462	    // too-large：已回复 413
463	    return;
464	  }
465	
466	  const method = String(req.method);
467	  const pathname = String(req.url ?? '/').split('?')[0]; // 查询串不参与匹配
468	
469	  // 管理入口（不消费任何业务序列）
470	  if (pathname === HEALTH_PATH) {
471	    if (method === 'GET') {
472	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
473	    } else {
474	      sendNotFound(res);
475	    }
476	    return;
477	  }
478	
479	  if (pathname === RELOAD_PATH) {
480	    if (method === 'POST') {
481	      const result = await triggerReload();
482	      sendJson(res, 200, result, result.version);
483	    } else {
484	      sendNotFound(res);
485	    }
486	    return;
487	  }
488	
489	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
490	  const state = activeState;
491	  const endpoint =
492	    method === 'GET' || method === 'POST'
493	      ? state.endpoints.get(`${method} ${pathname}`)
494	      : undefined;
495	
496	  if (!endpoint) {
497	    sendNotFound(res); // 未匹配请求：404，不消费
498	    return;
499	  }
500	
501	  const item = reserveNext(endpoint); // 完整接收后立即预留
502	  scheduleBusinessResponse(res, item, state.version);
503	}
504	
505	// ---------------------------------------------------------------------------
506	// 启动、信号处理
507	// ---------------------------------------------------------------------------
508	
509	function shutdown(): void {
510	  if (shuttingDown) {
511	    return;
512	  }
513	  shuttingDown = true;
514	  // 取消所有尚未发出的延迟响应
515	  for (const timer of pendingTimers) {
516	    clearTimeout(timer);
517	  }
518	  pendingTimers.clear();
519	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
520	  try {
521	    server.closeAllConnections();
522	  } catch {
523	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
524	  }
525	  server.close(() => process.exit(0));
526	  setTimeout(() => process.exit(0), 2000).unref();
527	}
528	
529	async function startServer(configArg: string, port: number): Promise<void> {
530	  configFile = path.resolve(configArg);
531	
532	  // 先读配置：配置无效时根本不会创建监听
533	  activeState = await loadStateFromFile(configFile, 1);
534	
535	  server = http.createServer((req, res) => {
536	    dispatch(req, res).catch(() => {
537	      try {
538	        req.socket.destroy();
539	      } catch {
540	        // 套接字可能已销毁
541	      }
542	    });
543	  });
544	
545	  await new Promise<void>((resolve, reject) => {
546	    server.once('error', reject);
547	    // 仅监听本机回环地址
548	    server.listen(port, '127.0.0.1', resolve);
549	  });
550	
551	  const address = server.address();
552	  const actualPort = typeof address === 'object' && address ? address.port : port;
553	  process.stdout.write(
554	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
555	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
556	  );
557	
558	  const onSignal = (): void => shutdown();
559	  process.on('SIGINT', onSignal);
560	  process.on('SIGTERM', onSignal);
561	}
562	
563	// ---------------------------------------------------------------------------
564	// 命令行
565	// ---------------------------------------------------------------------------
566	
567	function helpText(): string {
568	  return [
569	    APP_NAME,
570	    '',
571	    '可热更新的本地接口场景服务：在同一接口上按顺序返回预设响应，',
572	    '修改场景文件后通过管理入口热更新，更新期间服务不中断。',
573	    '',
574	    'Usage:',
575	    '  node app.ts [--help]',
576	    '  node app.ts serve --config <file> --port <port>',
577	    '',
578	    'Options (serve):',
579	    '  -c, --config <file>   本地 JSON 场景配置文件（必填）',
580	    '  -p, --port <number>   监听端口，0 表示由操作系统分配（必填）',
581	    '                        服务仅监听 127.0.0.1',
582	    '  -h, --help            显示本帮助',
583	    '',
584	    '管理入口（路径前缀 /__contractlab/ 为业务接口保留区之外的保留前缀）：',
585	    '  GET  /__contractlab/health   健康查询，返回当前配置版本',
586	    '  POST /__contractlab/reload   重新读取并热更新同一配置文件',
587	    '',
588	    '配置格式见 README.md。',
589	  ].join('\n');
590	}
591	
592	function cliFail(message: string): never {
593	  process.stderr.write(`${APP_NAME}: ${message}\n`);
594	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
595	  process.exit(2);
596	}
597	
598	interface ServeOptions {
599	  config: string;
600	  port: number;
601	}
602	
603	function parseServeArgv(argv: readonly string[]): ServeOptions {
604	  let config: string | undefined;
605	  let port: number | undefined;
606	
607	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
608	    if (inline !== undefined) {
609	      return [inline, index];
610	    }
611	    const value = argv[index + 1];
612	    if (value === undefined) {
613	      cliFail(`serve: 参数 ${flag} 缺少取值`);
614	    }
615	    return [value as string, index + 1];
616	  };
617	
618	  for (let i = 0; i < argv.length; i += 1) {
619	    const token = argv[i];
620	    if (token === '--help' || token === '-h') {
621	      process.stdout.write(`${helpText()}\n`);
622	      process.exit(0);
623	    }
624	
625	    let flag = token;
626	    let inline: string | undefined;
627	    const eq = token.indexOf('=');
628	    if (eq >= 0) {
629	      flag = token.slice(0, eq);
630	      inline = token.slice(eq + 1);
631	    }
632	
633	    if (flag === '--config' || flag === '-c') {
634	      [config, i] = readValue(flag, inline, i);
635	    } else if (flag === '--port' || flag === '-p') {
636	      let value: string;
637	      [value, i] = readValue(flag, inline, i);
638	      if (!/^\d+$/.test(value)) {
639	        cliFail(`serve: 端口必须是整数，收到 "${value}"`);
640	      }
641	      port = Number(value);
642	      if (port < 0 || port > 65535) {
643	        cliFail(`serve: 端口必须在 0 至 65535 之间，收到 ${port}`);
644	      }
645	    } else {
646	      cliFail(`serve: 不支持的命令行参数: ${token}`);
647	    }
648	  }
649	
650	  if (config === undefined) {
651	    cliFail('serve: 缺少必填参数 --config <file>');
652	  }
653	  if (port === undefined) {
654	    cliFail('serve: 缺少必填参数 --port <port>');
655	  }
656	  return { config, port };
657	}
658	
659	function main(): void {
660	  const argv = process.argv.slice(2);
661	
662	  // 保留行为：无参数、--help、-h 显示应用名与帮助
663	  if (
664	    argv.length === 0 ||
665	    (argv.length === 1 && (argv[0] === '--help' || argv[0] === '-h'))
666	  ) {
667	    process.stdout.write(`${helpText()}\n`);
668	    return;
669	  }
670	
671	  if (argv[0] === 'serve') {
672	    const options = parseServeArgv(argv.slice(1));
673	    startServer(options.config, options.port).catch((e: unknown) => {
674	      process.stderr.write(`${APP_NAME}: 启动失败：${describeError(e)}\n`);
675	      process.exit(1);
676	    });
677	    return;
678	  }
679	
680	  // 不支持的命令行参数：报错并以状态码 2 退出
681	  process.stderr.write(`${APP_NAME}: 不支持的命令行参数: ${argv.join(' ')}\n`);
682	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
683	  process.exit(2);
684	}
685	
686	main();
