  res: http.ServerResponse,
  item: ResponseSpec,
  version: number,
): void {
  const headers = versionHeaders(version);
  let contentTypeSet = false;
  for (const [name, value] of Object.entries(item.headers)) {
    if (name.toLowerCase() === 'content-type') {
      contentTypeSet = true;
    }
    headers[name] = value;
  }

